def parts(study):
    from scipy.optimize import least_squares
    tr = study['train']
    z = coords(study, np.r_[tr['x'], study['test']['x']])
    p = study['panel_b']
    u = p['u']
    v = p['v']

    def H(x, q):
        return D(np.sign(x) * np.maximum(abs(x) - q[0], 0) ** q[1])

    def e(q):
        f = H(u, q)
        return (f @ fit(f, v) - v).ravel()
    q = least_squares(e, [0.35, 1.5], bounds=([0.15, 0.6], [0.6, 2.5])).x
    b = H(z, q) @ fit(H(u, q), v)
    return (z, b)

def times(study):
    from scipy.optimize import least_squares
    t = study['eval_times']
    T = study['train']['traj']

    def F(p):
        return -np.expm1(-t[:, None] * p)

    def err(p):
        f = F(p)
        return (f @ fit(f, T.T) - T.T).ravel()
    return F(least_squares(err, [1.8, 0.42], bounds=([1.0, 0.15], [3.0, 0.85])).x)

def kernel(x, degree, decay):
    dot = x @ x.T / x.shape[1]
    dist = np.maximum(np.diag(dot)[:, None] + np.diag(dot) - 2 * dot, 0)
    return (1 + dot) ** degree + np.exp(-decay * dist)

def predict(study):
    (z, b) = parts(study)
    f = times(study)
    tr = study['train']
    n = len(tr['x'])
    modes = fit(f, tr['traj'].T).T
    sym = np.c_[0.3 * z + b, 0.3 * z - b]
    sep = np.c_[0.3 * z, b]
    designs = (np.arcsinh(sym), np.arcsinh(sep), sym, sep)

    def head(spec, target):
        (form, degree, decay, ridge) = spec
        k = kernel(designs[form], degree, decay)
        return k[n:, :n] @ np.linalg.solve(k[:n, :n] + ridge * np.eye(n), target)

    def blend(a, b, w, target):
        pred = head(a, target)
        return pred if w == 1 else w * pred + (1 - w) * head(b, target)
    y = blend(*((0, 2, 1.4, 1e-06), (2, 3, 0.15, 1e-06), 0.5), tr['y'])
    state = blend(*((1, 3, 0.15, 1e-06), (1, 3, 1.4, 1e-06), 0.25), modes) @ f.T
    return (y, state)
